import {bindChatThreadProject, createChatThread, deleteChatThread, resolveConnector, updateChatThread} from "@/db/repo";
import {pauseThreadGeneration} from "@/lib/agent/generationBatchRuntime";
import {useReferenceDraft} from "./useReferenceDraft";
import {TaskBoard} from "./TaskBoard";
import {TaskInspector} from "./TaskInspector";
import {AgentActivityNavigationProvider} from "./AgentActivityNavigation";
import {AgentComposerAttention} from "./AgentComposerAttention";
import {createAgentTaskForThread, setAgentTaskLifecycle} from "@/db/agentTasks";
import {getTaskDisplayState, TASK_STATE_LABELS} from "@/lib/agent/taskState";
import type {AgentReasoningEffort, AgentRun} from "@/domain/agent";
import {getReasoningPolicy} from "@/lib/ai/reasoningPolicy";
import {ContextUsageTrigger} from "./ContextUsagePanel";
import type {RunAction} from "./AgentRunDetails";
import {cancelAgentRun, resolveAgentToolApproval} from "@/db/agentTools";
import {Link, useNavigate} from "@tanstack/react-router";
import {useLiveQuery} from "dexie-react-hooks";
import {Button, Empty, Flexbox} from "@lobehub/ui";
import {useCallback, useEffect, useMemo, useRef, useState,} from "react";
import {toast} from "sonner";
import {ChatWorkspace} from "@/components/agent/ChatWorkspace";
import type {AgentInteractionMode, ChatSurfaceMode, ComposerProps} from "@/components/agent/composerTypes";
import {HomeWelcome} from "@/components/agent/HomeWelcome";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {Button as UiButton} from "@/components/ui/button";
import {Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle,} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {db} from "@/db/database";
import {type ChatThread, type Id, STUDIO_LIBRARY_ID} from "@/domain/types";
import {assertRetryConnector, beginAgentRun, canRetryRun} from "@/db/agentRuns";
import {executeChatRun, resumeChatRun} from "@/lib/agent/runChat";
import {recoverAbandonedRuns, withThreadRunLock} from "@/lib/agent/runOwnership";
import {recoverTaskWrapups} from "@/lib/agent/taskWrapup";
import {deriveChatTitle} from "@/lib/chatTitle";
import {discoverConnectorChatModels, runWithCompatibleChatModel} from "@/lib/ai/connectors";
import {
    buildChatModelOptions,
    type ChatModelCatalog,
    chatModelIssue,
    getChatModelPolicy,
    sameChatModelConnector,
} from "@/lib/ai/chatModelPolicy";

export function AgentChatPage({threadId, view}: { threadId?: Id; view?: "tasks" }) {
    return <AgentActivityNavigationProvider threadId={threadId}><AgentChatInner threadId={threadId}
                                                                                view={view}/></AgentActivityNavigationProvider>;
}

function AgentChatInner({threadId, view}: { threadId?: Id; view?: "tasks" }) {
    const navigate = useNavigate();
    const threads = useLiveQuery(() => db.chatThreads.orderBy("updatedAt").reverse().toArray(), []);
    const tasks = useLiveQuery(() => db.agentTasks.orderBy("updatedAt").reverse().toArray(), []);
    const boardRuns = useLiveQuery(() => view === "tasks" ? db.agentRuns.toArray() : Promise.resolve([] as AgentRun[]), [view]);
    const activeTask = tasks?.find((task) => task.threadId === threadId);
    const [taskInspectorOpen, setTaskInspectorOpen] = useState(false);
    const openBoard = () => {
        setTaskInspectorOpen(false);
        void navigate({to: "/agent/tasks"});
    };
    const connectors = useLiveQuery(() => db.connectors.toArray(), []);
    const projects = useLiveQuery(() => db.projects.orderBy("updatedAt").reverse().filter((project) => project.id !== STUDIO_LIBRARY_ID).toArray(), []);
    const activeThreadId = threadId;
    const [contextOpen, setContextOpen] = useState(false);
    const [sessionConnectorId, setSessionConnectorId] = useState<Id | undefined>();
    const [sessionModel, setSessionModel] = useState("");
    const [effortSelection, setEffortSelection] = useState<{
        threadId?: Id;
        connectorId?: string;
        baseUrl?: string;
        model: string;
        value?: AgentReasoningEffort
    }>();
    const [modelCatalog, setModelCatalog] = useState<ChatModelCatalog>();
    const [chatMode, setChatMode] = useState<ChatSurfaceMode>("agent");
    const [composerProjectId, setComposerProjectId] = useState<Id>();
    const [interactionSelection, setInteractionSelection] = useState<{ threadId?: Id; mode: AgentInteractionMode }>();
    const [sending, setSending] = useState(false);
    const [renameTarget, setRenameTarget] = useState<ChatThread>();
    const [renameValue, setRenameValue] = useState("");
    const [deleteTarget, setDeleteTarget] = useState<ChatThread>();
    const abortRef = useRef<AbortController | null>(null);
    const executionThreadRef = useRef<Id | undefined>(undefined);
    const sendLockRef = useRef(false);
    const selectionRevisionRef = useRef(0);

    useEffect(() => () => abortRef.current?.abort(), []);
    useEffect(() => {
        if (!activeThreadId) return;
        const pause = () => pauseThreadGeneration(activeThreadId);
        window.addEventListener('pagehide', pause);
        return () => {
            window.removeEventListener('pagehide', pause);
            pause();
        };
    }, [activeThreadId]);

    useEffect(() => {
        // Covers browser back/forward as well as links. New-thread sends assign their
        // destination before navigating, so that navigation does not cancel itself.
        if (executionThreadRef.current !== activeThreadId) abortRef.current?.abort();
    }, [activeThreadId]);

    const loaded = threads !== undefined && connectors !== undefined && projects !== undefined;
    const threadList = threads ?? [];
    const connectorList = connectors ?? [];

    const openThread = useCallback(
        (id: Id) => {
            if (executionThreadRef.current !== id) abortRef.current?.abort();
            void navigate({to: "/agent/$threadId", params: {threadId: id}});
        },
        [navigate],
    );

    const routedThread = useLiveQuery(
        async () => {
            if (!activeThreadId) {
                return {forId: null as Id | null, thread: null as ChatThread | null};
            }
            return {
                forId: activeThreadId,
                thread: (await db.chatThreads.get(activeThreadId)) ?? null,
            };
        },
        [activeThreadId],
    );

    useEffect(() => {
        if (!activeThreadId || routedThread === undefined) return;
        // Stale home null while deps already show a new id — ignore until query catches up.
        if (routedThread.forId !== activeThreadId) return;
        if (routedThread.thread === null) {
            void navigate({to: "/agent", replace: true});
        }
    }, [activeThreadId, routedThread, navigate]);

    const activeThread = useMemo(() => {
        const fromList = threadList.find((t) => t.id === activeThreadId);
        if (fromList) return fromList;
        if (
            routedThread &&
            routedThread.forId === activeThreadId &&
            routedThread.thread
        ) {
            return routedThread.thread;
        }
        return undefined;
    }, [threadList, activeThreadId, routedThread]);

    const messages = useLiveQuery(
        async () => {
            if (!activeThreadId) return [];
            return db.chatMessages.where("threadId").equals(activeThreadId).sortBy("createdAt");
        },
        [activeThreadId],
    );

    const compactions = useLiveQuery(() => activeThreadId ? db.contextCompactions.where("threadId").equals(activeThreadId).sortBy("createdAt") : [], [activeThreadId]);
    const runs = useLiveQuery(async () => {
        if (!activeThreadId) return [];
        return db.agentRuns.where("threadId").equals(activeThreadId).sortBy("createdAt");
    }, [activeThreadId]);

    useEffect(() => {
        const recover = () => void recoverAbandonedRuns().catch((error: unknown) => {
            toast.error(error instanceof Error ? error.message : "恢复执行状态失败");
        });
        recover();
        window.addEventListener("focus", recover);
        return () => window.removeEventListener("focus", recover);
    }, []);

    useEffect(() => {
        if (!activeThreadId) return;
        const recover = () => void recoverTaskWrapups(activeThreadId).catch((error: unknown) => {
            toast.error(error instanceof Error ? error.message : "恢复总结状态失败");
        });
        recover();
        window.addEventListener("focus", recover);
        return () => window.removeEventListener("focus", recover);
    }, [activeThreadId]);

    useEffect(() => {
        if (!loaded) return;
        if (activeThread) {
            setSessionConnectorId(activeThread.connectorId ?? connectorList[0]?.id);
            setSessionModel(activeThread.model?.trim() ?? "");
            return;
        }
        setSessionConnectorId((prev) => prev ?? connectorList[0]?.id);
    }, [loaded, activeThread?.id, activeThread?.connectorId, activeThread?.model, connectorList]);

    const selectedConnector = useMemo(() => {
        if (sessionConnectorId) {
            return connectorList.find((c) => c.id === sessionConnectorId) ?? connectorList[0];
        }
        return connectorList[0];
    }, [sessionConnectorId, connectorList]);

    const modelValue = sessionModel.trim();
    const projectId = activeThreadId ? activeThread?.projectId : composerProjectId;
    const references = useReferenceDraft(JSON.stringify([activeThreadId ?? "home", projectId]), projectId);
    const {text: draft, setText: setDraft} = references;
    const taskMode = activeThreadId ? Boolean(activeThread?.taskMode) : chatMode === "task";
    const projectRequired = taskMode && !projectId;
    const projectUnavailable = Boolean(projectId && projects && !projects.some((project) => project.id === projectId));
    const showHome = !activeThreadId && view !== "tasks";
    const interactionMode = interactionSelection?.threadId === activeThreadId ? interactionSelection?.mode ?? "smart" : activeThread?.interactionMode ?? "smart";
    const effortPolicy = selectedConnector ? getReasoningPolicy(selectedConnector, modelValue) : undefined;
    const effectiveEffort = effortSelection?.threadId === activeThreadId ? effortSelection : activeThread?.reasoningSelection;
    const reasoningEffort = effectiveEffort?.connectorId === selectedConnector?.id && effectiveEffort?.baseUrl === selectedConnector?.baseUrl && effectiveEffort?.model === modelValue && effectiveEffort.value && effortPolicy?.levels.includes(effectiveEffort.value) ? effectiveEffort.value : undefined;

    const selectionRef = useRef({connector: selectedConnector, model: modelValue, threadId: activeThreadId});
    selectionRef.current = {connector: selectedConnector, model: modelValue, threadId: activeThreadId};
    const modelPolicy = useMemo(() => getChatModelPolicy(selectedConnector, modelCatalog), [selectedConnector, modelCatalog]);
    const catalogMatches = sameChatModelConnector(selectedConnector, modelCatalog?.connector);
    const probingModels = Boolean(selectedConnector && (!catalogMatches || modelCatalog?.status === "loading"));

    useEffect(() => {
        if (!selectedConnector) return;
        let cancelled = false;
        const controller = new AbortController();
        setModelCatalog((previous) => ({
            connector: selectedConnector,
            status: "loading",
            models: [],
            incompatibleModels: sameChatModelConnector(selectedConnector, previous?.connector)
                ? previous?.incompatibleModels ?? [] : [],
        }));
        void discoverConnectorChatModels(selectedConnector, {signal: controller.signal})
            .then((result) => {
                if (cancelled) return;
                setModelCatalog((previous) => ({
                    connector: selectedConnector,
                    status: result.ok ? "ready" : "error",
                    models: result.ok ? result.models : [],
                    metadata: result.ok ? result.metadata : undefined,
                    incompatibleModels: result.ok ? result.incompatibleModels : previous?.incompatibleModels ?? [],
                }));
            });
        return () => {
            cancelled = true;
            controller.abort();
        };
    }, [selectedConnector?.id, selectedConnector?.definitionId, selectedConnector?.baseUrl, selectedConnector?.apiKey]);

    const handleNewTopic = useCallback(() => {
        if (abortRef.current) {
            abortRef.current.abort();
        }
        void (async () => {
            const thread = await createChatThread({
                connectorId: selectedConnector?.id,
                model: modelValue || undefined,
                projectId,
                taskMode,
            });
            openThread(thread.id);
        })().catch((error: unknown) => toast.error(error instanceof Error ? error.message : "创建对话失败"));
    }, [openThread, selectedConnector?.id, modelValue, projectId, taskMode]);

    const handleRenameThread = useCallback((thread: ChatThread) => {
        setRenameTarget(thread);
        setRenameValue(thread.title);
    }, []);

    const commitRename = useCallback(async () => {
        if (!renameTarget) return;
        await updateChatThread(renameTarget.id, {
            title: renameValue.trim() || renameTarget.title,
        });
        setRenameTarget(undefined);
    }, [renameTarget, renameValue]);

    const handleDeleteThread = useCallback((thread: ChatThread) => {
        setDeleteTarget(thread);
    }, []);

    const commitDelete = useCallback(async () => {
        if (!deleteTarget) return;
        if (abortRef.current && executionThreadRef.current === deleteTarget.id) {
            abortRef.current.abort();
        }
        await deleteChatThread(deleteTarget.id);
        if (activeThreadId === deleteTarget.id) {
            void navigate({to: "/agent", replace: true});
        }
        setDeleteTarget(undefined);
    }, [activeThreadId, deleteTarget, navigate]);

    const handleConnectorChange = useCallback(
        async (connectorId: string) => {
            selectionRevisionRef.current += 1;
            setSessionConnectorId(connectorId);
            if (activeThread) {
                await updateChatThread(activeThread.id, {connectorId});
            }
        },
        [activeThread],
    );

    const handleModelChange = useCallback(
        async (model: string) => {
            if (!buildChatModelOptions([], model, "", modelPolicy).includes(model.trim())) return;
            selectionRevisionRef.current += 1;
            setSessionModel(model);
            if (activeThread) {
                await updateChatThread(activeThread.id, {model});
            }
        },
        [activeThread, modelPolicy],
    );

    const handleProjectChange = useCallback(async (next?: Id) => {
        selectionRevisionRef.current += 1;
        if (activeThread) {
            if (!next) throw new Error("项目归属已锁定，不能清空");
            await bindChatThreadProject(activeThread.id, next, activeThread.projectId);
            return;
        }
        setComposerProjectId(next);
    }, [activeThread]);

    const handleStop = useCallback(() => {
        abortRef.current?.abort();
    }, []);

    const handleSend = useCallback(async () => {
        const submitted = references.capture();
        const content = submitted.text.trim();
        const attachments = submitted.attachments;
        if ((!content && !attachments.length) || submitted.imports.length || sendLockRef.current) return;
        if (projectRequired) {
            toast.error("任务模式请先选择项目");
            return;
        }
        if (projectUnavailable) {
            toast.error("项目已不可用，请选择其他项目开启新对话");
            return;
        }
        const connector = selectedConnector && {...selectedConnector};
        const model = modelValue;
        if (!connector) {
            toast.error("请先配置连接");
            return;
        }

        // Capture the UI selection before any await; thread persistence may still be catching up.
        const selectionRevision = selectionRevisionRef.current;
        const controller = new AbortController();
        sendLockRef.current = true;
        abortRef.current = controller;
        executionThreadRef.current = activeThreadId;
        setSending(true);
        try {
            const checked = await runWithCompatibleChatModel(connector, model, async () => {
                let thread = activeThread;
                if (!thread) {
                    thread = await createChatThread({
                        connectorId: connector.id,
                        model,
                        title: deriveChatTitle(content),
                        taskMode: chatMode === "task",
                        projectId
                    });
                    if (controller.signal.aborted) return;
                    executionThreadRef.current = thread.id;

                }
                const targetThread = thread;
                await withThreadRunLock(targetThread.id, async () => {
                    if (controller.signal.aborted) return;
                    // Acquire execution ownership before mounting detail recovery effects.
                    let owner = submitted;
                    if (!activeThread) {
                        const transfer = references.moveTo(JSON.stringify([targetThread.id, projectId]), submitted);
                        owner = transfer.submitted;
                        try {
                            await navigate({to: "/agent/$threadId", params: {threadId: targetThread.id}});
                        } catch (error) {
                            if (!transfer.restore()) throw new Error(`打开话题失败，发送草稿保留在「${targetThread.title}」中，请打开后重试`);
                            throw error;
                        }
                    }
                    if (controller.signal.aborted) return;
                    await updateChatThread(targetThread.id, {
                        interactionMode: activeThreadId ? interactionMode : "smart",
                        reasoningSelection: {
                            connectorId: connector.id,
                            baseUrl: connector.baseUrl,
                            model,
                            value: reasoningEffort
                        }
                    });
                    const run = await beginAgentRun({
                        threadId: targetThread.id,
                        connector,
                        model,
                        content,
                        attachments,
                        modelMetadata: catalogMatches ? modelCatalog?.metadata?.[model] : undefined,
                        reasoningEffort,
                        interactionMode: activeThreadId ? interactionMode : "smart"
                    });
                    references.acknowledge(owner);
                    await executeChatRun(run, connector.apiKey, controller);
                });

            }, {
                signal: controller.signal,
                isCurrent: () => selectionRevisionRef.current === selectionRevision &&
                    sameChatModelConnector(selectionRef.current.connector, connector) &&
                    selectionRef.current.model === model && selectionRef.current.threadId === activeThreadId,
            });
            if (!checked.ok && !checked.aborted) toast.error(checked.message);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "发送失败，请重试");
        } finally {
            sendLockRef.current = false;
            if (abortRef.current === controller) {
                abortRef.current = null;
                setSending(false);
            }
        }
    }, [navigate, draft, activeThread, activeThreadId, selectedConnector, modelValue, reasoningEffort, interactionMode, chatMode, projectId, projectRequired, projectUnavailable, references]);

    const handleRetry = useCallback(async (runId: string) => {
        if (sendLockRef.current) return;
        const controller = new AbortController();
        sendLockRef.current = true;
        abortRef.current = controller;
        executionThreadRef.current = activeThreadId;
        setSending(true);
        try {
            const previous = await db.agentRuns.get(runId);
            if (!previous || previous.threadId !== activeThreadId) throw new Error("执行不存在");
            const connector = await resolveConnector(previous.connector.id);
            if (!connector) throw new Error("原连接已删除，请重新配置后发送新消息");
            assertRetryConnector(previous, connector);
            const checked = await runWithCompatibleChatModel(connector, previous.model, () =>
                withThreadRunLock(previous.threadId, async () => {
                    if (controller.signal.aborted) return;
                    const run = await beginAgentRun({
                        threadId: previous.threadId,
                        connector,
                        model: previous.model,
                        retryOfRunId: previous.id
                    });
                    await executeChatRun(run, connector.apiKey, controller);
                }), {
                signal: controller.signal,
                isCurrent: () => selectionRef.current.threadId === previous.threadId,
            });
            if (!checked.ok && !checked.aborted) toast.error(checked.message);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "重新生成失败");
        } finally {
            sendLockRef.current = false;
            if (abortRef.current === controller) {
                abortRef.current = null;
                setSending(false);
            }
        }
    }, [activeThreadId]);

    const handleRunAction = useCallback(async (runId: string, action: RunAction, callId?: string) => {
        if (sendLockRef.current) return;
        const controller = new AbortController();
        sendLockRef.current = true;
        abortRef.current = controller;
        executionThreadRef.current = activeThreadId;
        setSending(true);
        try {
            const run = await db.agentRuns.get(runId);
            if (!run || run.threadId !== activeThreadId) throw new Error("执行不存在");
            if (action === "cancel") {
                await withThreadRunLock(run.threadId, async () => {
                    await cancelAgentRun(run.id);
                });
                return;
            }
            // Persist the decision independently of connector availability, so refusal
            // never requires sending another model request or having a working API key.
            if ((action === "approve" || action === "reject") && callId) {
                await withThreadRunLock(run.threadId, async () => {
                    if (controller.signal.aborted) return;
                    await resolveAgentToolApproval(run.id, callId, action);
                });
            }
            const outstanding = await db.agentToolCalls.where("runId").equals(run.id).filter((call) => call.status === "awaiting_approval").count();
            if (outstanding > 0) return;
            if (controller.signal.aborted) return;
            const connector = await resolveConnector(run.connector.id);
            if (!connector) throw new Error("决定已保存。原连接不存在，请恢复连接后继续或结束执行。");
            assertRetryConnector(run, connector);
            const checked = await runWithCompatibleChatModel(connector, run.model, () =>
                withThreadRunLock(run.threadId, async () => {
                    if (controller.signal.aborted) return;
                    await resumeChatRun(run.id, connector.apiKey, controller);
                }), {
                signal: controller.signal,
                isCurrent: () => selectionRef.current.threadId === run.threadId,
            });
            if (!checked.ok && !checked.aborted) toast.error(checked.message);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "处理执行失败");
        } finally {
            sendLockRef.current = false;
            if (abortRef.current === controller) {
                abortRef.current = null;
                setSending(false);
            }
        }
    }, [activeThreadId]);
    const onRunAction = useCallback((runId: string, action: RunAction, callId?: string) => {
        void handleRunAction(runId, action, callId);
    }, [handleRunAction]);

    const retryableRunId = useMemo(() => {
        const latest = runs?.at(-1);
        return latest && canRetryRun(latest, runs ?? [], messages ?? []) ? latest.id : undefined;
    }, [runs, messages]);
    const onRetryRun = useCallback((id: string) => {
        void handleRetry(id);
    }, [handleRetry]);

    const selectModelOptions = useMemo(() => buildChatModelOptions(
        catalogMatches ? modelCatalog?.models ?? [] : [], modelValue, "", modelPolicy,
    ).map((id) => ({label: id, value: id})), [catalogMatches, modelCatalog, modelValue, modelPolicy]);

    const routedThreadPending =
        Boolean(activeThreadId) &&
        (routedThread === undefined ||
            routedThread.forId !== activeThreadId ||
            (routedThread.forId === activeThreadId && routedThread.thread === null));

    if (!loaded || routedThreadPending) {
        return (
            <Flexbox align="center" justify="center" height="100%" style={{minHeight: "100%"}}>
                加载中…
            </Flexbox>
        );
    }

    if (connectorList.length === 0 && showHome) {
        return (
            <Flexbox
                align="center"
                justify="center"
                height="100%"
                gap={16}
                style={{minHeight: "100%", padding: 32}}
            >
                <Empty
                    title="还没有可用的连接"
                    description="对话需要先配置 OpenAI 兼容连接（Base URL + API Key）。密钥只保存在本机。"
                />
                <Link to="/connectors">
                    <Button type="primary">前往连接</Button>
                </Link>
                <Button onClick={openBoard}>先整理任务</Button>
            </Flexbox>
        );
    }

    const currentRun = runs?.filter((r) => r.threadId === activeThreadId).at(-1);
    const showRunStatus = currentRun && (currentRun.status === "running" || currentRun.status === "waiting_approval" || currentRun.status === "interrupted" || currentRun.status === "failed");
    const openTask = async () => {
        if (activeTask) {
            setTaskInspectorOpen(true);
            return;
        }
        if (!activeThreadId) return;
        try {
            await createAgentTaskForThread(activeThreadId, {
                projectId: activeThread?.projectId ?? projectId ?? "",
                title: activeThread?.title ?? "新任务",
                goal: messages?.find((message) => message.threadId === activeThreadId && message.role === "user")?.content || activeThread?.title || "补充任务目标",
                plan: currentRun?.plan,
            });
            setTaskInspectorOpen(true);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "关联任务失败");
        }
    };
    const composerProps: ComposerProps = {
        attachments: references.attachments,
        referenceImports: references.imports,
        onAttachReference: (attachment) => {
            if (!sendLockRef.current) references.attach(attachment);
        },
        onRemoveReference: (attachment) => {
            if (!sendLockRef.current) references.remove(attachment);
        },
        onImportReferences: (files) => {
            if (!sendLockRef.current) void references.importFiles(files);
        },
        onCancelReferenceImport: (id) => {
            if (!sendLockRef.current) references.cancel(id);
        },
        onRetryReferenceImport: (job) => {
            if (!sendLockRef.current) references.retry(job);
        },
        threadId: activeThreadId,
        projects: projects ?? [],
        projectId,
        projectRequired,
        projectLocked: sending || Boolean(activeThreadId && (activeThread?.projectId || messages?.length || runs?.length)),
        onProjectChange: handleProjectChange,
        blocked: projectUnavailable || Boolean(activeTask && activeTask.lifecycle !== "open"),
        readOnly: projectUnavailable,
        blockedReason: projectUnavailable ? "项目不可用 · 历史仍可查看，请新开项目对话" : undefined,
        status: projectUnavailable || activeTask || activeThread?.taskMode || showRunStatus || activeThreadId ? <>
            {activeThreadId &&
                <AgentComposerAttention threadId={activeThreadId} runs={runs ?? []} messages={messages ?? []}
                                        task={activeTask} projectUnavailable={projectUnavailable}
                                        onOpenTask={() => setTaskInspectorOpen(true)}/>}
            {projectUnavailable && <div className="agent-composer-run-status"><span>项目不可用 · 对话与记录仍保留</span>
                <button type="button" onClick={() => {
                    setComposerProjectId(undefined);
                    void navigate({to: "/agent"});
                }}>选择项目，开启新对话
                </button>
            </div>}
            {activeThread?.taskMode && !activeTask &&
                <div className="agent-composer-run-status"><span>需求沟通中 · 明确目标后，助手会建立任务</span></div>}
            {activeTask && <div className="agent-composer-task-summary">
                <button type="button" onClick={() => setTaskInspectorOpen(true)}>
                    <span className="agent-task-summary-label">任务</span><strong>{activeTask.title}</strong>
                    <span>{TASK_STATE_LABELS[getTaskDisplayState(activeTask, runs ?? [])]}{activeTask.plan.length > 0 ? ` · ${activeTask.plan.filter((item) => item.status === "completed").length}/${activeTask.plan.length}` : ""}</span>
                </button>
                {!projectUnavailable && activeTask.lifecycle !== "open" && <button type="button"
                                                                                   onClick={() => void setAgentTaskLifecycle(activeTask.id, "open").catch((error: Error) => toast.error(error.message))}>重新打开</button>}
            </div>}
            {showRunStatus ? (
                <div className="agent-composer-run-status" role="status">
                    <span><i/>{currentRun.status === "running" ? compactions?.at(-1)?.status === "running" ? "正在整理较早的对话…" : "正在执行" : currentRun.status === "waiting_approval" ? "等待你批准操作" : currentRun.status === "interrupted" ? currentRun.pauseReason === "model_step_limit" ? "执行已暂停，可继续下一段" : "执行已中断，进度已保存" : "执行未完成"}</span>
                    {currentRun.status === "running" &&
                        <button type="button" onClick={handleStop} disabled={!sending}>停止</button>}
                </div>
            ) : null}</> : undefined,
        contextUsage: <ContextUsageTrigger attachments={references.attachments} projectId={projectId}
                                           threadId={activeThreadId} task={activeTask} interactionMode={interactionMode}
                                           draft={draft}
                                           messages={messages?.filter((m) => m.threadId === activeThreadId) ?? []}
                                           runs={runs?.filter((r) => r.threadId === activeThreadId) ?? []}
                                           model={modelValue} connector={selectedConnector}
                                           modelMetadata={catalogMatches ? modelCatalog?.metadata : undefined}
                                           open={contextOpen} onOpenChange={setContextOpen}/>,

        reasoningEffort,
        onReasoningEffortChange: (value) => {
            if (!selectedConnector) return;
            const selection = {
                connectorId: selectedConnector.id,
                baseUrl: selectedConnector.baseUrl,
                model: modelValue,
                value
            };
            selectionRevisionRef.current += 1;
            setEffortSelection({...selection, threadId: activeThreadId});
            if (activeThreadId) void updateChatThread(activeThreadId, {reasoningSelection: selection}).catch(() => toast.error("推理设置保存失败，当前页面仍保留所选值"));
        },
        value: draft,
        sending,
        connectors: connectorList,
        selectedConnectorId: selectedConnector?.id,
        model: modelValue,
        modelOptions: selectModelOptions,
        modelMetadata: catalogMatches ? modelCatalog?.metadata : undefined,
        probingModels,
        modelPolicy,
        modelWarning: modelValue
            ? probingModels && !modelPolicy.incompatibleModels.includes(modelValue) && !modelPolicy.verified
                ? "正在确认 APIMart 模型类型…"
                : chatModelIssue(modelValue, modelPolicy)
            : undefined,
        chatMode,
        interactionMode,
        onChange: setDraft,
        onSend: () => void handleSend(),
        onStop: handleStop,
        onConnectorChange: (id) => void handleConnectorChange(id),
        onModelChange: (model) => void handleModelChange(model),
        onChatModeChange: (mode) => {
            selectionRevisionRef.current += 1;
            setChatMode(mode);
        },
        onInteractionModeChange: (mode) => {
            setInteractionSelection({threadId: activeThreadId, mode});
            if (activeThreadId) void updateChatThread(activeThreadId, {interactionMode: mode}).catch(() => toast.error("对话模式保存失败，请重试"));
        },
    };

    return (
        <>
            {view === "tasks" ? <TaskBoard tasks={tasks} runs={boardRuns} projects={projects ?? []}
                                           onOpenTask={(task) => openThread(task.threadId)}
                                           onBack={() => void navigate({to: "/agent"})}/> : showHome ? (
                <HomeWelcome
                    threads={threadList}
                    composer={composerProps}
                    tasks={tasks ?? []}
                    onOpenTasks={openBoard}
                    onSelectThread={openThread}
                />
            ) : (
                <ChatWorkspace
                    key={activeThreadId}
                    taskTitle={activeTask?.title}
                    taskGoal={activeTask?.goal}
                    onOpenTask={() => void openTask()}
                    onOpenTasks={openBoard}
                    threads={threadList}
                    activeThreadId={activeThreadId}
                    activeThread={activeThread}
                    messages={messages?.filter((message) => message.threadId === activeThreadId)}
                    runs={runs?.filter((run) => run.threadId === activeThreadId)}
                    retryableRunId={sending || projectUnavailable ? undefined : retryableRunId}
                    onRetryRun={onRetryRun}
                    onRunAction={onRunAction}
                    composer={composerProps}
                    onSelectThread={openThread}
                    onNewTopic={handleNewTopic}
                    onRenameThread={handleRenameThread}
                    onDeleteThread={handleDeleteThread}
                />
            )}

            {activeTask &&
                <TaskInspector projectName={projects?.find((project) => project.id === activeTask.projectId)?.name}
                               projectUnavailable={projectUnavailable} key={activeTask.id}
                               summaryModel={selectedConnector && modelValue ? {
                                   connector: selectedConnector,
                                   model: modelValue,
                                   modelMetadata: catalogMatches ? modelCatalog?.metadata?.[modelValue] : undefined,
                                   reasoningEffort
                               } : undefined} task={activeTask}
                               runs={(runs ?? []).filter((run) => run.threadId === activeThreadId)}
                               messages={(messages ?? []).filter((message) => message.threadId === activeThreadId)}
                               open={taskInspectorOpen} onOpenChange={setTaskInspectorOpen} onOpenBoard={openBoard}/>}

            <Dialog
                open={Boolean(renameTarget)}
                onOpenChange={(open) => !open && setRenameTarget(undefined)}
            >
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>重命名话题</DialogTitle>
                    </DialogHeader>
                    <Input
                        autoFocus
                        value={renameValue}
                        onChange={(event) => setRenameValue(event.target.value)}
                        onKeyDown={(event) => {
                            if (event.key === "Enter") {
                                event.preventDefault();
                                void commitRename();
                            }
                        }}
                    />
                    <DialogFooter>
                        <UiButton variant="outline" onClick={() => setRenameTarget(undefined)}>
                            取消
                        </UiButton>
                        <UiButton onClick={() => void commitRename()}>确定</UiButton>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <AlertDialog
                open={Boolean(deleteTarget)}
                onOpenChange={(open) => !open && setDeleteTarget(undefined)}
            >
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>删除话题</AlertDialogTitle>
                        <AlertDialogDescription>
                            删除「{deleteTarget?.title}」及其消息、关联任务与成果记录？无法恢复。
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>取消</AlertDialogCancel>
                        <AlertDialogAction
                            className="bg-destructive hover:bg-destructive/90"
                            onClick={() => void commitDelete()}
                        >
                            删除
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    );
}

import {useEffect, useRef, useState} from "react";
import {toast} from "sonner";
import {REFERENCE_LIMITS, referenceAttachment, type ReferenceAttachment} from "@/domain/references";
import {importReferenceFile, retryReferenceImport} from "@/lib/references/import";

export type ReferenceImportDraft = {
    id: string;
    filename: string;
    status: "importing" | "failed";
    error?: string;
    file: File;
    referenceId?: string
};
type DraftState = {
    text: string;
    textRevision: number;
    attachments: ReferenceAttachment[];
    imports: ReferenceImportDraft[]
};
type SubmittedDraft = Pick<DraftState, "text" | "textRevision" | "attachments" | "imports"> & {scope: string};
const EMPTY: DraftState = {text: "", textRevision: 0, attachments: [], imports: []};

export function useReferenceDraft(scope: string, projectId?: string) {
    const [drafts, setDrafts] = useState<Record<string, DraftState>>({});
    // Callbacks can edit while thread creation/navigation is awaiting. Keep a
    // synchronous snapshot so transfers inspect the latest edits even before paint.
    const currentDrafts = useRef(drafts);
    const revision = useRef(0);
    const controllers = useRef(new Map<string, AbortController>());
    const mounted = useRef(true);
    useEffect(() => {
        mounted.current = true;
        return () => {
            mounted.current = false;
            for (const controller of controllers.current.values()) controller.abort();
        };
    }, []);
    const draft = drafts[scope] ?? EMPTY;

    function publish(next: Record<string, DraftState>) {
        if (!mounted.current) return;
        currentDrafts.current = next;
        setDrafts(next);
    }

    function update(fn: (previous: DraftState) => DraftState, key = scope) {
        if (mounted.current) publish({...currentDrafts.current, [key]: fn(currentDrafts.current[key] ?? EMPTY)});
    }

    function setText(text: string) {
        update((previous) => ({...previous, text, textRevision: ++revision.current}));
    }

    function capture(): SubmittedDraft {
        const current = currentDrafts.current[scope] ?? EMPTY;
        return {scope, text: current.text, textRevision: current.textRevision, attachments: [...current.attachments], imports: [...current.imports]};
    }

    function attach(attachment: ReferenceAttachment) {
        update((previous) => ({
            ...previous,
            attachments: [...previous.attachments.filter((item) => item.referenceId !== attachment.referenceId), attachment]
        }));
    }

    async function importFiles(files: File[], retryId?: string) {
        if (!projectId) return;
        if (files.length > REFERENCE_LIMITS.selection) {
            toast.error(`每次最多导入 ${REFERENCE_LIMITS.selection} 个文件`);
            return;
        }
        const jobs = files.map((file) => ({
            id: crypto.randomUUID(),
            filename: file.name,
            status: "importing" as const,
            file
        }));
        update((previous) => ({...previous, imports: [...previous.imports, ...jobs]}));
        for (const job of jobs) controllers.current.set(job.id, new AbortController());
        for (const job of jobs) {
            const controller = controllers.current.get(job.id);
            if (!controller || controller.signal.aborted || !mounted.current) continue;
            try {
                const options = {
                    signal: controller.signal,
                    onProgress: (reference: { id: string }) => update((previous) => ({
                        ...previous,
                        imports: previous.imports.map((item) => item.id === job.id ? {
                            ...item,
                            referenceId: reference.id
                        } : item)
                    }))
                };
                const reference = retryId ? await retryReferenceImport(projectId, retryId, options) : await importReferenceFile(projectId, job.file, options);
                if (controller.signal.aborted) continue;
                update((previous) => ({
                    ...previous,
                    imports: previous.imports.map((item) => item.id === job.id ? {
                        ...item,
                        referenceId: reference.id
                    } : item)
                }));
                if (reference.status !== "ready" && reference.status !== "partial") throw new Error(reference.error ?? "解析未完成，请重试");
                update((previous) => ({
                    ...previous,
                    attachments: [...previous.attachments.filter((item) => item.referenceId !== reference.id), referenceAttachment(reference)],
                    imports: previous.imports.filter((item) => item.id !== job.id)
                }));
            } catch (error) {
                if (!controller.signal.aborted) update((previous) => ({
                    ...previous,
                    imports: previous.imports.map((item) => item.id === job.id ? {
                        ...item,
                        status: "failed",
                        error: error instanceof Error ? error.message : "导入失败"
                    } : item)
                }));
            } finally {
                controllers.current.delete(job.id);
            }
        }
    }

    function cancel(id: string) {
        controllers.current.get(id)?.abort();
        controllers.current.delete(id);
        update((previous) => ({...previous, imports: previous.imports.filter((item) => item.id !== id)}));
    }

    function clearSent(attachments: ReferenceAttachment[], key = scope) {
        update((previous) => ({
            ...previous,
            attachments: withoutSent(previous.attachments, attachments)
        }), key);
    }

    function acknowledge(submitted: SubmittedDraft) {
        update((previous) => ({
            ...previous,
            ...(previous.textRevision === submitted.textRevision ? {text: "", textRevision: ++revision.current} : {}),
            attachments: withoutSent(previous.attachments, submitted.attachments)
        }), submitted.scope);
    }

    function moveTo(key: string, submitted: SubmittedDraft) {
        if (!mounted.current) throw new Error("对话页面已关闭，草稿保留在原话题");
        // A created thread should have no compose session. Never overwrite a
        // destination session, even if its user has since edited back to empty.
        if (key in currentDrafts.current) throw new Error("新话题已有草稿，发送内容保留在原话题");
        const source = currentDrafts.current[submitted.scope] ?? EMPTY;
        const retained = {
            ...source,
            ...(source.textRevision === submitted.textRevision ? {text: "", textRevision: ++revision.current} : {}),
            attachments: withoutSent(source.attachments, submitted.attachments)
        };
        const destination: DraftState = {...EMPTY, text: submitted.text, textRevision: ++revision.current, attachments: submitted.attachments};
        const moved = {...submitted, scope: key, textRevision: destination.textRevision};
        publish({...currentDrafts.current, [submitted.scope]: retained, [key]: destination});
        return {
            submitted: moved,
            // Navigation may reject before showing the destination. Restore only
            // when neither owner has edited; otherwise keep the payload in the
            // created thread, which remains available through the thread list.
            restore: () => {
                if (!mounted.current) return false;
                const origin = currentDrafts.current[submitted.scope] ?? EMPTY;
                const target = currentDrafts.current[key] ?? EMPTY;
                if (source.textRevision !== submitted.textRevision || origin.textRevision !== retained.textRevision || target.textRevision !== moved.textRevision) return false;
                publish({...currentDrafts.current,
                    [submitted.scope]: {...origin, text: submitted.text, textRevision: ++revision.current,
                        attachments: [...origin.attachments.filter((item) => !submitted.attachments.some((sent) => sent.referenceId === item.referenceId)), ...submitted.attachments]},
                    [key]: {...target, text: "", textRevision: ++revision.current, attachments: withoutSent(target.attachments, submitted.attachments)}
                });
                return true;
            }
        };
    }

    return {
        ...draft,
        setText,
        capture,
        acknowledge,
        moveTo,
        attach,
        importFiles,
        cancel,
        clearSent,
        remove: (attachment: ReferenceAttachment) => clearSent([attachment]),
        retry: (job: ReferenceImportDraft) => {
            cancel(job.id);
            void importFiles([job.file], job.referenceId);
        }
    };
}

function withoutSent(attachments: ReferenceAttachment[], sent: ReferenceAttachment[]) {
    return attachments.filter((item) => !sent.some((snapshot) => snapshot.referenceId === item.referenceId && snapshot.revision === item.revision));
}
